import {mountHandover} from './handover-ui.js';
import {zonedToday} from './global.js';
import {DemoStore, today} from './demo-store.js';

const config=JSON.parse(document.getElementById('demo-config').textContent);
const root=document.getElementById('demo-root'), modal=document.getElementById('demo-modal');
let store;
try {store=new DemoStore(config.seed,localStorage,sessionStorage);}catch(error){root.textContent=error.message;throw error;}
const screen=config.screen;
const query=new URLSearchParams(location.search);
let page=1, search='', filter='all', city='all', category='all', attachments=[];
const h=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const t=(key)=>{key=config.translations._presentation?.[key]??key;const dict=store.locale==='ar'?config.translations:(config.translations._locales?.[store.locale]||{});return dict[key]||key;};
const name=item=>store.locale==='ar'&&item?.nameAr?item.nameAr:item?.name||'';
const money=(value,record)=>store.money(value,record);
const global=()=>config.seed.global;
const countryLabel=code=>t(store.countryName(code));
const countries=()=>global().countries.map(c=>[c.code,`${c.code} · ${t(c.name)}`]);
const currencies=()=>Object.entries(global().currencies).map(([code,label])=>[code,`${code} · ${t(label)}`]);
const periods=['night','week','month','year'];
const originalCurrencyNote=()=>info('Amounts remain in their original currency. Exchange-rate conversion is unavailable.');
const date=value=>store.date(value);
let country='all';

const route=(key,params={})=>{const base=config.routes[`manager.${key}`]||config.routes[`demo.${key}`]||config.routes['manager.dashboard'];const url=new URL(base);for(const [k,v]of Object.entries(params))if(v!==undefined)url.searchParams.set(k,v);return url.pathname+url.search;};
const go=(key,params={})=>location.assign(route(key,params));
const home=()=>store.user?.role==='owner'?'owner.dashboard':store.user?.role==='tenant'?'tenant.dashboard':'dashboard';
const scope=key=>store.user?.role==='manager'?key:`${store.user.role}.${key}`;
const propertyRoute=id=>route(store.user.role==='owner'?'owner.property':store.user.role==='tenant'?'tenant.property':'property-details',{id});
const propName=id=>name(store.property(id))||t('Unavailable');
const tenantName=id=>name(store.state.accounts.find(a=>a.id===id))||store.state.tenants.find(a=>a.id===id)?.name||id;
const btn=(label,action,data='',variant='secondary')=>`<button type="button" class="demo-button ${variant}" data-action="${h(action)}" data-id="${h(data)}">${h(t(label))}</button>`;
const link=(label,key,params={},variant='secondary')=>`<a class="demo-button ${variant}" href="${h(route(key,params))}">${h(t(label))}</a>`;
const tag=status=>`<span class="demo-tag ${['approved','confirmed','verified','active','completed','good','vacant'].includes(status)?'green':['rejected','cancelled','overdue','terminated','damaged'].includes(status)?'red':['pending','pending approval','maintenance','in progress','partial','draft'].includes(status)?'orange':''}">${h(t(status))}</span>`;
const title=(heading,sub='')=>`<h1 class="demo-title">${h(t(heading))}</h1><p class="demo-subtitle">${h(t(sub))}</p>`;
const info=text=>`<div class="demo-info">${h(t(text))}</div>`;
const card=(heading,body)=>`<section class="demo-card"><h2>${h(t(heading))}</h2>${body}</section>`;
const empty=(text='No matching demo records.')=>`<div class="demo-empty"><h2>${h(t('Nothing here yet'))}</h2><p>${h(t(text))}</p></div>`;
const pairs=values=>`<dl class="demo-summary">${values.map(([k,v])=>`<div><dt>${h(t(k))}</dt><dd>${h(v)}</dd></div>`).join('')}</dl>`;
const field=(label,name,value='',type='text',required=true,extra='')=>`<label>${h(t(label))}<input type="${type}" name="${name}" id="field-${name}" value="${h(value)}" ${required?'required':''} ${extra}></label>`;
const textarea=(label,key,value='',required=true)=>`<label class="full">${h(t(label))}<textarea name="${key}" ${required?'required':''}>${h(value)}</textarea></label>`;
const select=(label,key,values,value='')=>`<label>${h(t(label))}<select name="${key}" id="field-${key}" aria-label="${h(t(label))}" required>${values.map(v=>{const [id,text]=Array.isArray(v)?v:[v,t(v)];return `<option value="${h(id)}" ${String(id)===String(value)?'selected':''}>${h(text)}</option>`;}).join('')}</select></label>`;
const password=(label,key)=>`<label>${h(t(label))}<div class="password-field"><input name="${key}" id="password-${key}" aria-label="${h(t(label))}" type="password" required minlength="8" autocomplete="off"><button class="demo-button secondary" type="button" data-action="toggle-password" data-id="${key}" aria-label="${h(t('Show password'))}">${h(t('Show'))}</button></div></label>`;
const submit=label=>`<button class="demo-button" type="submit">${h(t(label))}</button>`;
const form=(kind,body,button='Save demo changes')=>`<form class="demo-form" data-form="${kind}" novalidate><div class="demo-error" id="form-error" role="alert" hidden></div>${body}<div class="demo-actions">${submit(button)}${btn('Cancel','close')}</div></form>`;
const actionBar=(body)=>`<div class="demo-toolbar"><div class="demo-actions">${body}</div></div>`;
const image=(image,alt='',cls='')=>`<img class="demo-property-image ${cls}" src="${h(/^data:image\/(png|jpeg|webp);base64,/.test(image||'')?image:'/assets/aqar/images/'+(/^[a-z0-9]+\.jpg$/.test(image||'')?image:config.seed.properties[0].image))}" alt="${h(alt)}">`;
function toast(text){const target=document.getElementById('demo-toast');target.textContent=t(text);target.hidden=false;clearTimeout(toast.timer);toast.timer=setTimeout(()=>target.hidden=true,4500);}
function show(heading,body){attachments=[];document.getElementById('modal-content').innerHTML=`<h2 id="modal-title">${h(t(heading))}</h2>${body}`;if(!modal.open)modal.showModal();}
function notice(){show('Not available in this demo',info('This optional feature is not available in this demo. No external action was performed.')+actionBar(btn('Close','close')));}
function formError(error){const target=modal.open?modal.querySelector('#form-error'):root.querySelector('#form-error');if(target){target.textContent=t(error.message);target.hidden=false;target.scrollIntoView({block:'nearest'});}else show('Please check your entry',`<div class="demo-error">${h(t(error.message))}</div>${btn('Close','close')}`);}
function table(headers,rows){return rows.length?`<div class="demo-table-wrap"><table class="demo-table"><thead><tr>${headers.map(v=>`<th>${h(t(v))}</th>`).join('')}</tr></thead><tbody>${rows.map(row=>`<tr>${row.map(c=>`<td>${c}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:empty();}
function paginate(rows){const count=Math.max(1,Math.ceil(rows.length/6));page=Math.min(page,count);return {rows:rows.slice((page-1)*6,page*6),footer:`<div class="demo-pagination"><span>${h(t('Sample records'))}: ${rows.length} · ${h(t('Page'))} ${page} / ${count}</span><div class="demo-actions">${btn('Previous','previous').replace('<button ',`<button ${page===1?'disabled':''} `)}${btn('Next','next').replace('<button ',`<button ${page===count?'disabled':''} `)}</div></div>`};}
function searchBar(statuses=[],properties=false){return `<div class="demo-toolbar"><label><span class="sr-only">${h(t('Search'))}</span><input class="demo-search" id="demo-search" type="search" placeholder="${h(t('Search sample records'))}" value="${h(search)}"></label><div class="demo-actions">${statuses.length?`<select id="demo-filter" class="demo-search" aria-label="${h(t('Status'))}"><option value="all">${h(t('All statuses'))}</option>${statuses.map(s=>`<option value="${h(s)}" ${filter===s?'selected':''}>${h(t(s))}</option>`).join('')}</select>`:''}${properties?`<select id="demo-country" class="demo-search" aria-label="${h(t('Country'))}"><option value="all">${h(t('All countries'))}</option>${[...new Set(store.properties({browse:true}).map(p=>p.country))].map(c=>`<option value="${c}" ${country===c?'selected':''}>${h(countryLabel(c))}</option>`).join('')}</select><select id="demo-city" class="demo-search" aria-label="${h(t('City'))}"><option value="all">${h(t('All cities'))}</option>${[...new Set(store.properties({browse:true}).map(p=>p.city))].map(v=>`<option ${city===v?'selected':''}>${h(v)}</option>`).join('')}</select><select id="demo-category" class="demo-search" aria-label="${h(t('Category'))}"><option value="all">${h(t('All categories'))}</option>${[...new Set(store.state.properties.map(p=>p.category))].map(v=>`<option value="${h(v)}" ${category===v?'selected':''}>${h(t(v))}</option>`).join('')}</select>`:''}${btn('Clear filters','clear-filters')}</div></div>`;}
const publicScreens=new Set(['welcome','onboarding','login','register','account-type','forgot-password','reset-password','session-expired','logout']);
function guard(){if(screen==='logout'){store.logout();go('login');return false;}if(publicScreens.has(screen))return true;if(!store.user){go(store.session?'session-expired':'login');return false;}if(screen.startsWith('owner.')&&store.user.role!=='owner'||screen.startsWith('tenant.')&&store.user.role!=='tenant'||Object.keys(config.routes).some(k=>k===`manager.${screen}`)&&store.user.role!=='manager'||['property-edit','designs'].includes(screen)&&store.user.role!=='manager'){go(home());return false;}return true;}
function shell(){const isPublic=publicScreens.has(screen);document.body.classList.toggle('demo-auth',isPublic);document.documentElement.lang=store.locale;document.documentElement.dir=store.locale==='ar'?'rtl':'ltr';
  const roles={manager:'Property manager / broker',owner:'Property owner',tenant:'Tenant'};
  const unread=!isPublic&&store.preferences.notifications?store.records('notifications').filter(n=>!n.read).length:0;
  const notificationLink=isPublic?'':link('Notifications',scope('notifications')).replace('</a>',`${unread?`<span class="demo-notification-dot" aria-hidden="true">${unread}</span>`:''}</a>`);
  const language=btn(store.locale==='en'?'العربية':'English','language');
  document.getElementById('demo-header').innerHTML=`${isPublic?`<a class="demo-header-brand" href="${route('welcome')}"><strong>Aqar</strong> · ${h(t('Property portal'))}</a>`:`<span class="demo-mobile-toggle">${btn('Menu','menu','','secondary')}</span><span class="demo-top-user"><strong>${h(name(store.user))}</strong><span class="demo-role-note">${h(t(roles[store.user.role]))}</span></span>`}<div class="demo-actions">${language}${!isPublic?`${notificationLink}${link('Profile','profile')}${link('Logout','logout')}`:link('Demo login','login')}</div>`;
  if(isPublic){document.getElementById('demo-sidebar').innerHTML='';return;}
  const manager=[['handover','Unit inventory & handover','fact_check'],['dashboard','Dashboard','grid_view'],['properties','Properties','apartment'],['units','Units','meeting_room'],['owners','Owners','business'],['tenants','Tenants','group'],['bookings','Bookings','event'],['contracts','Contracts','description'],['payments','Payments','payments'],['receivables','Rent collection','account_balance_wallet'],['maintenance','Maintenance','build'],['furniture','Furniture inventory','chair'],['documents','Documents','folder'],['reports','Reports & analytics','monitoring'],['settings','Settings','settings']];
  const owner=[['owner.handover','Unit inventory & handover','fact_check'],['owner.dashboard','Owner dashboard','grid_view'],['owner.properties','My properties','apartment'],['owner.occupancy','Occupancy overview','key'],['owner.income','Rental income','payments'],['owner.expenses','Expenses','receipt_long'],['owner.profit','Net profit','trending_up'],['owner.reports','Financial reports','monitoring'],['owner.maintenance','Maintenance approvals','build'],['owner.furniture','Furniture inventory','chair'],['owner.documents','Documents','folder'],['owner.settings','Settings','settings']];
  const tenant=[['tenant.handover','Unit inventory & handover','fact_check'],['tenant.dashboard','Tenant dashboard','grid_view'],['tenant.browse','Browse properties','apartment'],['tenant.bookings','My bookings','event'],['tenant.contracts','My contracts','description'],['tenant.payments','My payments','payments'],['tenant.maintenance','Maintenance requests','build'],['tenant.inspection','Condition inspection','fact_check'],['tenant.settings','Settings','settings']];
  const nav=store.user.role==='manager'?manager:store.user.role==='owner'?owner:tenant;
  document.getElementById('demo-sidebar').innerHTML=`<a class="manager-brand" href="${route(home())}"><span class="brand-icon material-symbols-outlined">apartment</span><span><strong>Aqar</strong><small>${h(t('PROPERTY PORTAL'))}</small></span></a><div class="sidebar-caption">${h(t(roles[store.user.role]))}</div><nav>${nav.map(([key,label,icon])=>`<a class="sidebar-link ${screen===key?'is-active':''}" href="${route(key)}" ${screen===key?'aria-current="page"':''}><span class="material-symbols-outlined" aria-hidden="true">${icon}</span>${h(t(label))}</a>`).join('')}</nav><div class="sidebar-bottom">${store.user.role==='manager'?link('Design references','designs'):''}<p>Aqar · ${h(t('Property management'))}</p></div>`;
}
function auth(){const demoAccounts=config.seed.accounts;
  const roleSelect=select('Account type','role',[['manager',t('Property manager / broker')],['owner',t('Property owner')],['tenant',t('Tenant')]],query.get('role')||'tenant');
  if(['welcome','onboarding','account-type'].includes(screen)){const choosing=screen==='account-type';return `<div class="global-welcome"><div class="global-welcome-top"><strong>Aqar <span lang="ar">عقار</span></strong>${btn(store.locale==='en'?'العربية':'English','language')}</div>${!choosing?`<section class="global-welcome-hero"><div><span class="auth-eyebrow">${h(t('PROPERTY WITHOUT BORDERS'))}</span><h1>${h(t('A world of places. One Aqar.'))}</h1><p>${h(t('Manage, own or find your next place — wherever life takes you.'))}</p>${link('Get started','account-type',{},'')}</div></section>`:title('How will you use Aqar?','Choose your workspace')}<div class="global-role-grid">${[['manager','Property manager / broker','Manage your portfolio','domain'],['owner','Property owner','Follow your investments','key'],['tenant','Tenant','Find your next place','home']].map(([role,label,description,icon])=>`<a class="global-role-card" href="${route(choosing?'register':'login',{role})}"><span class="material-symbols-outlined" aria-hidden="true">${icon}</span><span><strong>${h(t(label))}</strong><small>${h(t(description))}</small></span><span aria-hidden="true">↗</span></a>`).join('')}</div><div class="global-welcome-footer">${h(t('Already a member?'))} ${link('Sign in','login')}<p>${h(t('Local preview. No real transactions.'))}</p></div></div>`;}
  if(screen==='session-expired')return `<div class="auth-panel">${title('Session expired','Your demo session has ended. No records were removed.')}${link('Sign in again','login',{},'')}</div>`;
  if(screen==='login')return `<div class="aqar-login-layout"><section class="aqar-login-story" aria-label="${h(t('Global real estate'))}"><img class="login-property-photo" src="/assets/aqar/images/dbb2a71ef1c083e218bb.jpg" alt="${h(t('Residential architecture in Riyadh'))}"><div class="login-image-copy"><span class="auth-eyebrow">${h(t('PROPERTY WITHOUT BORDERS'))}</span><h2>${h(t('Remarkable places.'))}<br>${h(t('Thoughtfully managed.'))}</h2><p>${h(t('A closer connection to the properties that matter.'))}</p><span class="login-location">${h(t('Al Yasmin · Riyadh'))}</span></div></section><section class="aqar-login-form"><div class="login-topline"><a class="login-wordmark" href="${route('welcome')}" aria-label="Aqar">Aqar <span lang="ar">عقار</span></a>${btn(store.locale==='en'?'العربية':'English','language')}</div><div class="login-form-inner"><span class="auth-eyebrow">${h(t('YOUR PROPERTY WORKSPACE'))}</span>${title('Welcome back','Sign in to your property workspace.')}<form class="demo-form login-fields" data-form="login" novalidate><div class="demo-error" id="form-error" role="alert" hidden></div>${field('Email address','email',query.get('role')?query.get('role')+'@aqar.demo':'','email',true,'autocomplete="username" placeholder="name@example.com"')}${password('Password','password')}<div class="login-options"><label class="check-label"><input type="checkbox" name="remember">${h(t('Remember me'))}</label><a href="${route('forgot-password')}">${h(t('Forgot password?'))}</a></div>${submit('Sign in')}<span class="login-register">${h(t('New to Aqar?'))} <a href="${route('account-type')}">${h(t('Create an account'))}<span aria-hidden="true"> ↗</span></a></span></form><details class="preview-access"><summary>${h(t('Preview access'))}</summary><p>${h(t('Local preview only. Use fictional information.'))}</p>${demoAccounts.map(a=>btn(t(a.role==='manager'?'Property manager / broker':a.role==='owner'?'Property owner':'Tenant'),'fill-account',a.role)).join('')}</details></div><div class="login-footer"><span>© ${new Date().getFullYear()} Aqar</span><span>${h(t('Real estate, thoughtfully connected.'))}</span></div></section></div>`;
  if(screen==='register')return `<div class="auth-panel demo-card">${title('Create demo account','Use fictional information and a demo-only password.')}${form('register',`${field('Full name','name')}${field('Email','email','','email')}${select('Country','country',countries(),store.preferences.country)}${field('Phone country code','phoneCode',store.preferences.phoneCode)}${roleSelect}${password('Demo password','password')}${password('Confirm password','confirm')}`,'Register demo account')}${link('Already have an account?','login')}</div>`;
  if(screen==='forgot-password')return `<div class="auth-panel demo-card">${title('Forgot password','This demonstration sends no email or SMS.')}${form('forgot',field('Demo account email','email','manager@aqar.demo','email'),'Continue to demo reset')}${link('Back to login','login')}</div>`;
  return `<div class="auth-panel demo-card">${title('Reset password','Demo reset only · No email verification or secure recovery')}${form('reset-password',`${field('Demo account email','email',query.get('email')||'manager@aqar.demo','email')}${password('New demo password','password')}${password('Confirm password','confirm')}`,'Reset demo password')}</div>`;
}
function metrics(){const v=store.totals();const owner=store.user.role==='owner',tenant=store.user.role==='tenant';const items=tenant?[['My bookings',store.records('bookings').length],['Outstanding',money(v.outstanding)],['Verified payments',money(v.collected)],['Maintenance requests',store.records('maintenance').length]]:owner?[['My properties',v.properties],['Rental income',money(v.collected)],['Expenses',money(v.expense)],['Net profit',money(v.profit)],['Occupancy',`${v.occupancy}%`]]:[['Properties',v.properties],['Units',v.units],['Verified payments',money(v.collected)],['Pending bookings',v.pending],['Occupancy',`${v.occupancy}%`]];return `<p class="muted">${h(t('Financial totals in'))} ${h(store.preferences.currency)} · ${h(t('No currency conversion'))}</p><div class="demo-metrics">${items.map(([key,value],i)=>`<div class="metric ${['Rental income','Verified payments','Net profit'].includes(key)?'green':''} ${['Outstanding','Rental income','Verified payments','Expenses','Net profit'].includes(key)?'money-metric':''}"><span>${h(t(key))}</span><strong>${h(value)}</strong></div>`).join('')}</div>`;}
function dashboard(){const role=store.user.role;const bookings=store.records('bookings');const recent=bookings.slice(0,3);return title(role==='owner'?'Owner dashboard':role==='tenant'?'Tenant dashboard':'Property operations & collections')+metrics()+actionBar(role==='manager'?link('Add property','add-property-1',{},'')+btn('Create booking','new-booking')+btn('Record simulated payment','new-payment'):role==='tenant'?link('Browse properties','tenant.browse',{},'')+btn('Submit maintenance request','new-maintenance'):link('My properties','owner.properties',{},'')+link('Maintenance approvals','owner.maintenance'))+`<div class="demo-grid">${card('Recent bookings',recent.length?recent.map(b=>`<div class="demo-record"><strong>${h(propName(b.propertyId))}</strong><p>${h(date(b.start))} → ${h(date(b.end))} · ${h(money(b.amount,b))}</p>${tag(b.status)} ${btn('View details','booking-details',b.id)}</div>`).join(''):empty())}${card('Portfolio overview',pairs([['Properties',String(store.properties().length)],['Current occupancy',`${store.totals().occupancy}%`],['Collected',money(store.totals().collected)],['Financial activity',t('SIMULATED · No money moved')]])+link(role==='tenant'?'My payments':'Financial reports',scope(role==='tenant'?'payments':'reports')))}</div>`;}
function propertyList(){let values=store.properties({browse:store.user.role==='tenant'}).filter(p=>(filter==='all'||p.publication===filter||p.availability===filter)&&(country==='all'||p.country===country)&&`${name(p)} ${p.city} ${p.district}`.toLowerCase().includes(search.toLowerCase())&&(city==='all'||p.city===city)&&(category==='all'||p.category===category));const p=paginate(values);return title(store.user.role==='owner'?'My properties':store.user.role==='tenant'?'Browse properties':'Properties management')+actionBar(store.user.role==='manager'?link('Add property','add-property-1',{},'')+btn('Export sample CSV','export','properties'):'')+searchBar(['published','draft','unpublished','available','unavailable','maintenance'],true)+(p.rows.length?`<div class="demo-grid">${p.rows.map(item=>`<article class="demo-card">${image(item.cover||item.image,name(item))}<div class="demo-actions">${tag(item.category)}${tag(item.availability)}${tag(item.publication)}${tag(item.listingType)}${tag(item.policy==='instant'?'Instant booking':'Request to book')}</div><h2 style="margin-top:14px">${h(name(item))}</h2><p>${h(countryLabel(item.country))} · ${h(t(item.city))} · ${h(item.district)}</p><p><strong>${h(money(item.price,item))}</strong> · ${h(t(item.listingType==='sale'?'Sale price':`per ${item.ratePeriod}`))}</p>${pairs([['Planned units',item.unitCount],['Publishing',t(item.publication)]])}<div class="demo-actions" style="margin-top:18px"><a class="demo-button" href="${propertyRoute(item.id)}">${h(t('View details'))}</a>${store.user.role==='manager'?link('Edit','property-edit',{id:item.id})+btn('Delete','delete-property',item.id,'danger'):''}</div></article>`).join('')}</div>`:empty())+p.footer;}
function propertyDetails(){const id=query.get('id')||store.properties({browse:store.user.role==='tenant'})[0]?.id;const p=store.property(id);if(!p||!store.canSeeProperty(id,store.user.role==='tenant'))return empty('This property is not assigned to your demo account.');const units=store.state.units.filter(u=>u.propertyId===id);return title(name(p),`${t(p.city)} · ${t(p.category)}`)+image(p.cover||p.image,name(p),'demo-property-hero')+actionBar(store.user.role==='tenant'?link('Availability calendar','tenant.calendar',{id},'')+(p.availability==='available'&&p.listingType!=='sale'?link(p.policy==='instant'?'Book instantly (demo)':'Request to book','tenant.booking',{id}):info('This property is unavailable for booking.')):store.user.role==='manager'?link('Edit property','property-edit',{id},'')+link('Manage units','units',{propertyId:id})+btn('Delete','delete-property',id,'danger'):link('Maintenance approvals','owner.maintenance'))+(p.photos?.length?card('Photos',photos(p.photos)):'')+originalCurrencyNote()+card('Property overview',`<p>${h(p.description)}</p>${pairs([['Country',countryLabel(p.country)],['Region',p.region||''],['Postal code',p.postalCode||''],['Time zone',p.timeZone],['Furnishing',t(p.furnishing||'not specified')],['Equipment / finishing (demo description)',p.equipment||''],['Availability',t(p.availability)],['Amenities',(p.amenities||[]).join(', ')],['Owner',store.state.owners.find(o=>o.id===p.ownerId)?.name||''],['City',t(p.city)],['Address',p.address],['Rental rate',money(p.price,p)],['Booking policy',t(p.policy==='instant'?'Instant booking':'Request to book')],['Publishing',t(p.publication)]])}`)+card('Units',table(['Unit','Beds','Area','Rent','Status','Actions'],units.map(u=>[h(u.name),h(u.beds),h(store.area(u.area)),h(money(u.price,u)),tag(u.status),store.user.role==='manager'?link('View unit','unit-details',{id:u.id}):h(t('Sample unit'))])))+card('Related screens',actionBar(link('Documents',scope('documents'))+link('Furniture inventory',store.user.role==='tenant'?'tenant.inspection':scope('furniture'))));}
function units(){const id=query.get('propertyId');const values=store.records('units').filter(u=>(!id||u.propertyId===id)&&`${u.name} ${propName(u.propertyId)}`.toLowerCase().includes(search.toLowerCase())&&(filter==='all'||u.status===filter));const p=paginate(values);return title('Units management')+actionBar(btn('Add unit','new-unit','','')+btn('Export sample CSV','export','units'))+searchBar(['vacant','occupied','maintenance'])+table(['Unit','Property','Rent','Status','Actions'],p.rows.map(u=>[h(u.name),h(propName(u.propertyId)),h(money(u.price,u)),tag(u.status),link('View details','unit-details',{id:u.id})+' '+btn('Edit','edit-unit',u.id)+btn('Delete','delete-unit',u.id,'danger')]))+p.footer;}
function unitDetails(){const unit=store.records('units').find(u=>u.id===(query.get('id')||store.records('units')[0]?.id));if(!unit)return empty();return title(`${t('Unit')} ${unit.name}`,propName(unit.propertyId))+(unit.photos?.length?card('Photos',photos(unit.photos)):'')+card('Unit specifications',pairs([['Bedrooms',unit.beds],['Bathrooms',unit.baths],['Area',store.area(unit.area)],['Rent',money(unit.price,unit)],['Status',t(unit.status)],['Currency',unit.currency],['Rental duration',t(unit.ratePeriod)],['Furnishing',t(unit.furnishing||'not specified')],['Equipment / finishing (demo description)',unit.equipment||''],['Amenities',(unit.amenities||[]).join(', ')]])+actionBar(btn('Edit unit','edit-unit',unit.id)+btn('Delete','delete-unit',unit.id,'danger')+link('View property','property-details',{id:unit.propertyId})+link('Furniture inventory','furniture')+link('Maintenance','maintenance')));}
function wizard(){const step=screen==='property-edit'?1:Number(screen.match(/(\d)$/)?.[1]||1),editId=query.get('id');let draft=store.state.draft||{};if(editId&&draft.editId!==editId){const p=store.property(editId);if(!p)return empty();draft={...p,editId};store.state.draft=draft;store.save();}if(!editId&&draft.editId){store.state.draft={};draft=store.state.draft;store.save();}const d={name:'',category:'Apartment',city:'',country:store.preferences.country,currency:store.preferences.currency,timeZone:store.preferences.timeZone,region:'',postalCode:'',listingType:'rent',publication:'published',availability:'available',ratePeriod:'month',minNights:1,amenities:'',address:'',district:'',ownerId:'owner1',unitCount:1,price:7500,policy:'request',published:'true',...draft};const labels=['Basic information','Location','Ownership & management','Units & rental','Photos & documents','Review'];
  let body='';if(step===1)body=field('Property name','name',d.name)+select('Category','category',['Apartment','Villa','Floor','Chalet','Farm','Commercial','Rest house'],d.category)+textarea('Description','description',d.description||'',false)+select('Country','country',countries(),d.country)+select('Currency','currency',currencies(),d.currency)+select('Listing type','listingType',['rent','sale'],d.listingType);
  if(step===2)body=select('Country','country',countries(),d.country)+field('State / province / region','region',d.region||'','text',false)+field('City','city',d.city)+field('District / neighborhood','district',d.district,'text',false)+field('Street address','address',d.address)+field('Postal code','postalCode',d.postalCode||'','text',false)+field('Property time zone','timeZone',d.timeZone)+field('Latitude','latitude',d.latitude??'','number',false,'step="any" min="-90" max="90"')+field('Longitude','longitude',d.longitude??'','number',false,'step="any" min="-180" max="180"');
  if(step===3)body=select('Property owner','ownerId',store.state.owners.map(o=>[o.id,o.name]),d.ownerId)+field('Assigned manager','manager',d.manager||'Sultan Al-Najdi')+field('Management fee (%)','fee',d.fee||'8.5','number',true,'min="0" max="100" step="0.1"');
  if(step===4)body=select('Furnishing','furnishing',['not specified','furnished','unfurnished'],d.furnishing||'not specified')+field('Equipment / finishing (demo description)','equipment',d.equipment||'','text',false)+field('Planned units','unitCount',d.unitCount,'number',true,'min="1" max="20"')+field('Price in property currency','price',d.price,'number',true,'min="0.001" step="0.001"')+select('Currency','currency',currencies(),d.currency)+select('Rental duration','ratePeriod',periods,d.ratePeriod)+field('Minimum stay (nights)','minNights',d.minNights,'number',true,'min="1"')+field('Amenities (comma separated)','amenities',Array.isArray(d.amenities)?d.amenities.join(', '):d.amenities||'','text',false)+select('Availability','availability',['available','unavailable','maintenance'],d.availability)+select('Publication','publication',['draft','published','unpublished'],d.publication)+select('Reprice all units when currency changes','repriceUnits',[['false',t('No')],['true',t('Yes')]],d.repriceUnits||'false')+info('Currency changes require a new price for every unit and are blocked when history exists.')+select('Booking policy','policy',[['request',t('Request to book')],['instant',t('Instant booking')]],d.policy);
  if(step===5)body=info('Media stays on this device. No upload service is connected.')+`<label>${h(t('Attach small photos'))}<input name="photos" type="file" accept="image/png,image/jpeg,image/webp" multiple data-photos></label>${photos(d.photos||[])}${btn('Remove photos','clear-property-photos')}<div class="demo-photo-grid">${image(d.cover||d.image||config.seed.properties[0].image,t('Sample cover'))}</div>`+field('Sample document reference','document',d.document||'Sample title deed', 'text',false);
  if(step===6)body=pairs([['Property name',d.name],['Category',t(d.category)],['City',t(d.city)],['Address',d.address],['Owner',store.state.owners.find(o=>o.id===d.ownerId)?.name||''],['Planned units',d.unitCount],['Price',money(d.price,d)],['Country',countryLabel(d.country)],['Currency',d.currency],['Time zone',d.timeZone],['Publication',d.publication],['Availability',d.availability],['Rental duration',d.ratePeriod],['Amenities',Array.isArray(d.amenities)?d.amenities.join(', '):d.amenities||''],['Booking policy',t(d.policy==='instant'?'Instant booking':'Request to book')]])+info('Save creates or updates a fictional property in this browser only.');
  return title(editId?'Edit property':'Add new property',`${t('Step')} ${step} / 6 · ${t(labels[step-1])}`)+`<nav class="demo-stepper" aria-label="${h(t('Property steps'))}">${labels.map((v,i)=>`<a href="${route(`add-property-${i+1}`,{id:editId||undefined})}" data-action="wizard-link" data-id="${i+1}" ${step===i+1?'aria-current="step"':''}>${i+1} · ${h(t(v))}</a>`).join('')}</nav><section class="demo-card"><form class="demo-form columns" data-form="wizard" data-step="${step}" novalidate><div class="demo-error full" id="form-error" role="alert" hidden></div>${body}<div class="demo-actions full">${step>1?btn('Previous step','wizard-back',step-1):link('Cancel','properties')}${submit(step===6?'Save sample property':'Next step')}${btn('Save draft','save-draft')}</div></form></section>`;}
function listRecords(kind,heading){const values=store.records(kind).filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase())||propName(r.propertyId).toLowerCase().includes(search.toLowerCase())).filter(r=>filter==='all'||r.status===filter);const p=paginate(values);let headers=[],rows=[],actions='';
  if(kind==='bookings'){headers=['Property','Tenant','Dates','Amount','Status','Actions'];rows=p.rows.map(b=>[h(propName(b.propertyId)),h(tenantName(b.tenantId)),`${h(date(b.start))} → ${h(date(b.end))}`,h(money(b.amount,b)),tag(b.status),btn('View details','booking-details',b.id)+(store.user.role==='manager'&&b.status==='pending'?btn('Approve','approve-booking',b.id,'success')+btn('Reject','reject-booking',b.id,'danger'):'')+(store.user.role!=='owner'&&!['rejected','cancelled'].includes(b.status)?btn('Cancel booking','cancel-booking',b.id,'danger'):'')]);actions=store.user.role!=='owner'?btn('Create booking','new-booking','',''):'';}
  if(kind==='payments'){headers=['Property','Booking','Simulated amount','Date','Status','Actions'];rows=p.rows.map(pay=>[h(propName(pay.propertyId)),h(pay.bookingId),h(money(pay.amount,pay)),h(date(pay.date)),tag(pay.status),btn('View details','payment-details',pay.id)+(store.user.role==='manager'&&pay.status==='pending'?btn('Verify','verify-payment',pay.id,'success'):'')]);actions=store.user.role!=='owner'?btn('Record simulated payment','new-payment','',''):'';}
  if(kind==='contracts'){headers=['Sample contract','Property','Amount','Status','Actions'];rows=p.rows.map(c=>[h(c.title),h(propName(c.propertyId)),h(money(c.amount,c)),tag(c.status),btn('View sample contract','contract-details',c.id)+(store.user.role==='manager'?btn('Change status','contract-status',c.id):'')]);actions=store.user.role==='manager'?btn('Create sample contract','new-contract','',''):'';}
  if(kind==='maintenance'){headers=['Request','Property','Priority','Status','Actions'];rows=p.rows.map(m=>[h(m.title),h(propName(m.propertyId)),tag(m.priority),tag(m.status),btn('View details','maintenance-details',m.id)+(store.user.role==='owner'&&m.status==='pending approval'?btn('Approve','approve-maintenance',m.id,'success')+btn('Reject','reject-maintenance',m.id,'danger'):'')]);actions=store.user.role!=='owner'?btn('Submit maintenance request','new-maintenance','',''):'';}
  if(kind==='documents'){headers=['Document','Property','Type','Actions'];rows=p.rows.map(d=>[h(d.title),h(propName(d.propertyId)),h(t(d.type)),btn('Download sample','download-document',d.id)]);actions=store.user.role==='manager'?btn('Add sample document','new-document','',''):'';}
  if(kind==='furniture'){headers=['Item','Property','Room','Quantity','Condition','Actions'];rows=p.rows.map(f=>[h(t(f.name)),h(propName(f.propertyId)),h(t(f.room)),h(f.quantity),tag(f.condition),store.user.role==='manager'?btn('Update condition','furniture-condition',f.id):btn('View details','furniture-details',f.id)]);actions=store.user.role==='manager'?btn('Add inventory item','new-furniture','',''):'';}
  return title(heading)+actionBar(actions+btn('Export sample CSV','export',kind))+(['payments','contracts'].includes(kind)?info('All financial and contract records are simulated. No money is moved and no legal agreement is executed.'):'')+searchBar([...new Set(store.records(kind).map(r=>r.status).filter(Boolean))])+table(headers,rows)+p.footer;}
function people(kind){const values=store.state[kind].filter(r=>`${r.name} ${r.email}`.toLowerCase().includes(search.toLowerCase()));const p=paginate(values);return title(kind==='owners'?'Owners management':'Tenants management')+actionBar(btn(kind==='owners'?'Add owner':'Add tenant','new-person',kind,''))+searchBar()+table(['Name','Demo email','Actions'],p.rows.map(r=>[h(r.name),h(r.email),btn('View details','person-details',`${kind}:${r.id}`)]))+p.footer;}
function finances(){const totals=store.totals();const key=screen.split('.').pop();if(key==='occupancy'){return title('Occupancy overview')+metrics()+table(['Property','Units','Occupied'],store.properties().map(p=>[h(name(p)),h(store.state.units.filter(u=>u.propertyId===p.id).length),h(new Set(store.state.bookings.filter(b=>b.propertyId===p.id&&['approved','confirmed'].includes(b.status)&&b.start<=today()&&b.end>today()).map(b=>b.unitId)).size)]));}
  return title(key==='expenses'?'Expenses':key==='profit'?'Net profit':key==='income'?'Rental income':screen==='receivables'?'Rent collection & receivables':'Financial reports')+metrics()+actionBar(btn('Export sample CSV','export',key==='expenses'?'expenses':'payments')+(store.user.role==='manager'?btn('Record simulated payment','new-payment'):'')+link(store.user.role==='manager'?'Operational reports':'My properties',store.user.role==='manager'?'reports-operations':'owner.properties'))+info('Totals are derived from visible sample records. Pending payments are not counted as collected income.')+originalCurrencyNote()+card('Totals by original currency',table(['Currency','Verified payments','Expenses','Net profit'],store.currencyTotals().map(v=>[h(v.currency),h(money(v.collected,v.currency)),h(money(v.expense,v.currency)),h(money(v.profit,v.currency))])))+card('Financial summary',pairs([['Expected',money(totals.expected)],['Verified payments',money(totals.collected)],['Outstanding',money(totals.outstanding)],['Expenses',money(totals.expense)],['Net profit',money(totals.profit)]]))+(key==='expenses'?table(['Expense','Property','Amount','Date'],store.records('expenses').map(e=>[h(e.title),h(propName(e.propertyId)),h(money(e.amount,e)),h(date(e.date))])):table(['Booking','Property','Due','Paid','Outstanding','Status'],store.records('bookings').filter(b=>!['rejected','cancelled'].includes(b.status)).map(b=>[h(b.id),h(propName(b.propertyId)),h(money(b.amount,b)),h(money(store.paid(b.id),b)),h(money(Math.max(0,b.amount-store.paid(b.id)),b)),tag(store.paid(b.id)>=b.amount?'paid':b.start<today()?'overdue':'pending')])));}
function calendar(){const id=query.get('id')||store.properties({browse:true})[0]?.id,p=store.property(id);if(!p?.published)return empty();const units=store.state.units.filter(u=>u.propertyId===id);const selected=query.get('unitId')||units.find(u=>u.status==='vacant')?.id||units[0]?.id;const start=query.get('start')||zonedToday(p.timeZone);return title('Availability calendar',name(p))+card('Select a date range',form('calendar',select('Unit','unitId',units.map(u=>[u.id,u.name]),selected)+field('Check-in','start',start,'date')+field('Check-out','end',query.get('end')||addDays(start,1),'date'),'Check availability'))+`<div class="demo-calendar">${Array.from({length:14},(_,i)=>{const day=addDays(start,i),busy=p.availability!=='available'||p.listingType==='sale'||['maintenance','unavailable'].includes(units.find(u=>u.id===selected)?.status)||store.conflicts(selected,day,addDays(day,1));return `<div class="demo-day ${busy?'busy':''}"><strong>${h(date(day))}</strong><p>${h(t(busy?'Booked':'Available'))}</p></div>`;}).join('')}</div>`+actionBar(link('Continue to booking','tenant.booking',{id,unitId:selected,start,end:query.get('end')||addDays(start,1)},''));}
function bookingForm(){const values=store.properties({browse:true}).filter(p=>p.availability==='available'&&p.listingType!=='sale');const id=query.get('id')||values[0]?.id;if(!values.length||(query.get('id')&&!values.some(p=>p.id===id)))return empty('This property is unavailable for booking.');return form('booking',info('Instant-booking properties confirm locally. Request-to-book properties await manager approval. No payment is processed.')+info(`${t('Dates use the property time zone')}: ${store.property(id)?.timeZone||''}`)+select('Property','propertyId',values.map(p=>[p.id,name(p)]),id)+select('Unit','unitId',store.state.units.filter(u=>u.propertyId===id&&!['maintenance','unavailable'].includes(u.status)).map(u=>[u.id,`${u.name} · ${money(u.price,u)}`]),query.get('unitId')||'')+(store.user.role==='manager'?select('Tenant','tenantId',store.state.tenants.map(t=>[t.id,t.name])):'')+field('Check-in','start',query.get('start')||addDays(zonedToday(store.property(id).timeZone),1),'date')+field('Check-out','end',query.get('end')||addDays(zonedToday(store.property(id).timeZone),3),'date'),'Submit demo booking');}
const addDays=(date,n)=>{const d=new Date(`${date}T12:00:00Z`);if(!Number.isFinite(d.getTime()))return today();d.setUTCDate(d.getUTCDate()+n);return d.toISOString().slice(0,10);};
function profile(){const u=store.user;if(screen==='profile-edit')return title('Edit profile')+card('Demo profile',form('profile',field('Full name','name',u.name)+select('Country','country',countries(),u.country||store.preferences.country)+field('Phone country code','phoneCode',u.phoneCode||store.preferences.phoneCode)+field('Phone','phone',u.phone||'','tel',false),'Save demo profile'));if(screen==='profile-password')return title('Change password')+card('Demo password',form('change-password',password('Current password','oldPassword')+password('New demo password','password')+password('Confirm password','confirm'),'Change demo password'));return title('Profile')+card('Demo account',pairs([['Name',name(u)],['Email',u.email],['Account type',t(u.role)],['Phone',u.phone||'—']])+actionBar(link('Edit profile','profile-edit',{},'')+link('Change password','profile-password')+link('Logout','logout')));}
function settings(){const p=store.preferences;return title('Settings & preferences')+originalCurrencyNote()+card('Global preferences',form('settings',select('Country','country',countries(),p.country)+select('Preferred currency','currency',currencies(),p.currency)+select('Language','locale',Object.entries(global().languages),store.locale)+field('Time zone','timeZone',p.timeZone)+select('Date format','dateFormat',['yyyy-MM-dd','dd/MM/yyyy','MM/dd/yyyy'],p.dateFormat)+select('Measurement units','measurement',[['sqm',t('Square meters')],['sqft',t('Square feet')]],p.measurement)+field('Phone country code','phoneCode',p.phoneCode)+`<label class="check-label"><input type="checkbox" name="notifications" ${p.notifications?'checked':''}>${h(t('Show demo notifications'))}</label>`,'Save demo settings'))+card('Formatting preview',pairs([['Date',store.date(zonedToday(p.timeZone))],['Time zone',p.timeZone],['Area',store.area(100)],['Phone country code',p.phoneCode],['Notification alerts',t(p.notifications?'Enabled':'Disabled')],['Country',countryLabel(p.country)]]))+card('Demo lifecycle',info('Reset restores the fictional seed on this device. Website and mobile changes do not synchronize.')+actionBar(btn('Reset demo data','reset','','danger')+btn('Simulate session expiry','expire')+link('Switch demo account','login')));}

function notifications(){const values=store.records('notifications');return title('Notifications')+actionBar(btn('Mark all as read','read-all'))+(values.length?values.map(n=>card(n.read?'Read':'Unread',`<p>${h(t(n.title))}</p>${btn('Mark as read','read-notification',n.id)}`)).join(''):empty());}
function inspection(){return title('Property condition inspection')+card('Record condition',form('inspection',select('Property','propertyId',store.properties().map(p=>[p.id,name(p)]))+select('Condition','condition',['good','damaged','not assessed'])+textarea('Inspection notes','notes')+`<label>${h(t('Attach small photos'))}<input type="file" accept="image/png,image/jpeg,image/webp" multiple data-photos></label>`,'Save sample inspection'))+card('Inspection history',store.records('inspections').map(i=>`<div class="demo-record"><strong>${h(propName(i.propertyId))}</strong> ${tag(i.condition)}<p>${h(i.notes)}</p><p>${h(i.date)}</p>${photos(i.photos)}</div>`).join('')||empty());}
function photos(values=[]){return `<div class="demo-photo-grid">${values.filter(v=>/^data:image\/(png|jpeg|webp);base64,/.test(v)).map(v=>`<img src="${h(v)}" alt="${h(t('Local sample photo'))}">`).join('')}</div>`;}
function gallery(){return title('Design references','Original Stitch screens are retained as read-only references. Their preview notices do not change demo records.')+`<div class="demo-grid">${Object.entries(config.routes).filter(([k])=>k.startsWith('manager.')).map(([key,url])=>{const label=key.slice(8).replaceAll('-',' '),path=new URL(url).pathname;return card(label,`<a class="demo-button secondary" href="/designs${path==='/'?'/dashboard':path}">${h(t('Open original design'))}</a>`);}).join('')}</div>`;}
function render(){if(!guard())return;shell();let body='';if(publicScreens.has(screen))body=auth();else if(['dashboard','dashboard-ar','owner.dashboard','tenant.dashboard'].includes(screen))body=dashboard();else if(['properties','owner.properties','tenant.browse'].includes(screen))body=propertyList();else if(['property-details','owner.property','tenant.property'].includes(screen))body=propertyDetails();else if(screen==='units')body=units();else if(screen==='unit-details')body=unitDetails();else if(screen.startsWith('add-property-')||screen==='property-edit')body=wizard();else if(screen==='tenant.calendar')body=calendar();else if(screen==='tenant.booking')body=title('Booking request')+card('Choose property and dates',bookingForm());else if(screen.includes('notifications')||screen==='notifications')body=notifications();else if(screen.includes('settings'))body=settings();else if(screen.startsWith('profile'))body=profile();else if(screen==='tenant.inspection')body=inspection();else if(screen==='designs')body=gallery();else if(screen==='owners'||screen==='tenants')body=people(screen);else {const kind=screen.split('.').pop();if(['bookings','payments','contracts','maintenance','documents','furniture'].includes(kind))body=listRecords(kind,{bookings:store.user.role==='tenant'?'My bookings':'Bookings management',payments:store.user.role==='tenant'?'My payments':'Payments management',contracts:store.user.role==='tenant'?'My contracts':'Contracts management',maintenance:store.user.role==='owner'?'Maintenance approvals':store.user.role==='tenant'?'Maintenance requests':'Maintenance management',documents:'Documents',furniture:'Furniture inventory'}[kind]);else body=finances();}root.innerHTML=body;if(screen.endsWith('handover'))mountHandover(root,store,t);else if(screen.includes('furniture')||screen==='tenant.inspection')root.insertAdjacentHTML('afterbegin',link('Unit inventory & handover',scope('handover')));const banner=document.querySelector('.demo-banner');banner.hidden=true;document.title=`${t(config.screen.replaceAll('-',' '))} | Aqar`;}

function maintenanceForm(){attachments=[];return form('maintenance',select('Property','propertyId',store.properties().map(p=>[p.id,name(p)]))+field('Request title','title')+textarea('Description','description')+select('Priority','priority',['low','medium','high'])+field('Estimated cost in property currency','cost','0','number',false,'min="0"')+`<label>${h(t('Attach small photos'))}<input type="file" accept="image/png,image/jpeg,image/webp" multiple data-photos></label>`,'Submit sample request');}
function paymentForm(){return form('payment',info('SIMULATED · No money moved')+select('Booking','bookingId',store.records('bookings').filter(b=>['approved','confirmed'].includes(b.status)).map(b=>[b.id,`${propName(b.propertyId)} · ${b.id} · ${t('Outstanding')}: ${money(Math.max(0,b.amount-store.paid(b.id)),b)}`]))+field('Simulated amount in booking currency','amount','','number',true,'min="1" step="1"')+(store.user.role==='manager'?select('Status','status',['pending','verified']):'')+textarea('Demo note','note','Simulated receipt only',false),'Record simulated payment');}
function unitForm(id){attachments=[];const u=store.state.units.find(u=>u.id===id)||{},area=store.preferences.measurement==='sqft'?Number(u.area||115)*10.7639104:u.area||115;return form('unit',select('Furnishing','furnishing',['not specified','furnished','unfurnished'],u.furnishing||'not specified')+field('Equipment / finishing (demo description)','equipment',u.equipment||'','text',false)+`<input type="hidden" name="id" value="${h(id||'')}"><input type="hidden" name="areaUnit" value="${store.preferences.measurement}">`+select('Property','propertyId',store.properties().map(p=>[p.id,name(p)]),u.propertyId)+field('Unit name','name',u.name||'')+field('Price in property currency','price',u.price||7500,'number',true,'min="0.001" step="0.001"')+field('Bedrooms','beds',u.beds??2,'number',true,'min="0"')+field('Bathrooms','baths',u.baths??2,'number',true,'min="0"')+field(store.preferences.measurement==='sqft'?'Area (sq ft)':'Area (sq m)','area',Number(area.toFixed(2)),'number',true,'min="0.01" step="0.01"')+field('Amenities (comma separated)','amenities',(u.amenities||[]).join(', '),'text',false)+select('Rental duration','ratePeriod',periods,u.ratePeriod||'month')+field('Minimum stay (nights)','minNights',u.minNights||1,'number',true,'min="1"')+select('Status','status',['vacant','occupied','maintenance','unavailable'],u.status||'vacant')+photos(u.photos||[])+`<label>${h(t('Attach small photos'))}<input type="file" accept="image/png,image/jpeg,image/webp" multiple data-photos></label>`,'Save sample unit');}

function details(kind,id){const record=store.records(kind).find(r=>r.id===id);if(!record)throw Error('Record not found.');
 if(kind==='bookings')show('Booking details',pairs([['Property',propName(record.propertyId)],['Tenant',tenantName(record.tenantId)],['Check-in',date(record.start)],['Check-out',date(record.end)],['Amount',money(record.amount,record)],['Status',t(record.status)],['Country',countryLabel(record.country||store.property(record.propertyId).country)],['Time zone',record.timeZone||store.property(record.propertyId).timeZone],['Rental duration',t(record.ratePeriod||store.property(record.propertyId).ratePeriod)]])+actionBar((store.user.role==='manager'&&record.status==='pending'?btn('Approve','approve-booking',id,'success')+btn('Reject','reject-booking',id,'danger'):'')+btn('Close','close')));
 if(kind==='payments')show('Simulated payment details',info('SIMULATED · No money moved')+pairs([['Property',propName(record.propertyId)],['Amount',money(record.amount,record)],['Status',t(record.status)],['Date',date(record.date)],['Demo note',record.note]])+actionBar(store.user.role==='manager'&&record.status==='pending'?btn('Verify','verify-payment',id,'success'):btn('Close','close')));
 if(kind==='contracts')show('Sample contract',`<div class="demo-contract"><h3>${h(record.title)}</h3>${info('SAMPLE DOCUMENT · Not a legally executed agreement')}${pairs([['Property',propName(record.propertyId)],['Tenant',tenantName(record.tenantId)],['Dates',`${record.start} → ${record.end}`],['Amount',money(record.amount,record)],['Status',`${t(record.status)} (${t('demo')})`]])}</div>`+actionBar(btn('Print sample','print')+btn('Download sample','download-contract',id)+btn('Close','close')));
 if(kind==='maintenance')show('Maintenance request',pairs([['Request title',record.title],['Property',propName(record.propertyId)],['Description',record.description],['Status',t(record.status)],['Estimated cost (SAR)',money(record.cost,record)]])+photos(record.photos)+actionBar(store.user.role==='owner'&&record.status==='pending approval'?btn('Approve','approve-maintenance',id,'success')+btn('Reject','reject-maintenance',id,'danger'):store.user.role==='manager'?btn('Change status','maintenance-status',id):'')+card('Comments',record.comments.map(c=>`<p><strong>${h(c.name)}</strong> · ${h(c.date)}<br>${h(c.text)}</p>`).join('')||`<p>${h(t('No comments yet.'))}</p>`)+form('comment',`<input type="hidden" name="id" value="${h(id)}">`+textarea('Comment','text'),'Add comment'));
}
function confirmAction(label,action,id){show('Confirm demonstration action',`<p>${h(t(label))}</p>${info('This changes fictional local records only.')}<div class="demo-actions">${btn('Confirm',action,id,'danger')}${btn('Cancel','close')}</div>`);}
function download(filename,text,type='text/plain;charset=utf-8'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function closeAndRender(message){if(modal.open)modal.close();render();if(message)toast(message);}
function storeDraft(formElement){const data=Object.fromEntries(new FormData(formElement));delete data.photos;if(attachments.length){data.cover=attachments[0];data.photos=attachments;}store.saveDraft(data);}
function requireForm(formElement){if(!formElement.checkValidity()){formElement.reportValidity();throw Error('Please complete the required fields correctly.');}}
document.addEventListener('submit',async event=>{const f=event.target.closest('[data-form]');if(!f)return;event.preventDefault();if(f.dataset.saving)return;let submitButton=f.querySelector('[type=submit]');try{requireForm(f);f.dataset.saving='true';f.setAttribute('aria-busy','true');if(submitButton)submitButton.disabled=true;const data=Object.fromEntries(new FormData(f));const kind=f.dataset.form;
  if(kind==='login'){await store.login(data.email,data.password,!!data.remember);go(home());return;}
  if(kind==='register'){await store.register(data);await store.login(data.email,data.password);go(home());return;}
  if(kind==='forgot'){if(!store.state.accounts.some(a=>a.email.toLowerCase()===data.email.toLowerCase()))throw Error('Demo account not found.');go('reset-password',{email:data.email});return;}
  if(kind==='reset-password'){await store.resetPassword(data.email,data.password,data.confirm);go('login',{reset:'1'});return;}
  if(kind==='change-password'){await store.changePassword(data.oldPassword,data.password,data.confirm);closeAndRender('Demo password changed.');return;}
  if(kind==='profile'){store.updateProfile(data);go('profile');return;}
  if(kind==='settings'){store.setPreferences({...data,notifications:!!data.notifications});closeAndRender('Demo settings saved.');return;}
  if(kind==='wizard'){storeDraft(f);const step=Number(f.dataset.step);if(step===6){const draft=store.state.draft;const property=store.saveProperty(draft,draft.editId);store.state.draft={};store.save();go('property-details',{id:property.id,created:'1'});}else go(`add-property-${step+1}`,{id:query.get('id')||undefined});return;}
  if(kind==='booking'){store.createBooking(data);if(modal.open)modal.close();go(scope('bookings'),{created:'1'});return;}
  if(kind==='calendar'){store.validDates(data.start,data.end,store.property(query.get('id'))?.timeZone);if(store.conflicts(data.unitId,data.start,data.end))throw Error('These dates overlap an approved booking.');go('tenant.calendar',{id:query.get('id'),...data});return;}
  if(kind==='payment')store.recordPayment(data);
  if(kind==='unit')store.saveUnit({...data,...(attachments.length?{photos:attachments}: {})},data.id||undefined);
  if(kind==='contract')store.createContract(data);
  if(kind==='contract-status')store.updateContract(data.id,data.status);
  if(kind==='maintenance'){store.createMaintenance({...data,photos:attachments});attachments=[];}
  if(kind==='maintenance-status')store.updateMaintenance(data.id,data.status);
  if(kind==='comment')store.comment(data.id,data.text);
  if(kind==='inspection'){store.inspect({...data,photos:attachments});attachments=[];}
  if(kind==='person'){store.requireRole('manager');if(!/^\S+@\S+\.\S+$/.test(data.email))throw Error('Enter a name and a valid email.');store.transaction(()=>store.state[data.kind].push({id:store.id(data.kind),name:data.name,email:data.email}));}
  if(kind==='document'){store.requireRole('manager');store.transaction(()=>store.state.documents.push({id:store.id('d'),title:data.title,propertyId:data.propertyId,type:'Sample attachment'}));}
  if(kind==='furniture'){store.requireRole('manager');store.transaction(()=>store.state.furniture.push({id:store.id('f'),name:data.name,propertyId:data.propertyId,room:data.room,quantity:Number(data.quantity),condition:'not assessed'}));}
  if(kind==='furniture-condition'){store.requireRole('manager');store.transaction(()=>{const item=store.state.furniture.find(f=>f.id===data.id);if(!item)throw Error('Record not found.');item.condition=data.condition;});}
  closeAndRender('Sample records updated locally.');
 }catch(error){formError(error);}finally{delete f.dataset.saving;f.removeAttribute('aria-busy');if(submitButton)submitButton.disabled=false;}});
document.addEventListener('click',event=>{const el=event.target.closest('[data-action]');if(!el)return;const action=el.dataset.action,id=el.dataset.id;event.preventDefault();try {
 if(action==='close'){if(modal.open)modal.close();else go(home());return;}
 if(action==='language'){store.setLocale(store.locale==='en'?'ar':'en');render();return;}
 if(action==='toggle-password'){const input=document.getElementById(`password-${id}`);input.type=input.type==='password'?'text':'password';el.textContent=t(input.type==='password'?'Show':'Hide');return;}
 if(action==='fill-account'){document.getElementById('field-email').value=`${id}@aqar.demo`;document.getElementById('password-password').value='Demo123!';return;}
 if(action==='menu'){const open=document.body.classList.toggle('sidebar-open');el.setAttribute('aria-expanded',String(open));return;}
 if(action==='clear-filters'){search='';filter=city=category=country='all';page=1;render();return;}
 if(action==='previous'||action==='next'){page=Math.max(1,page+(action==='next'?1:-1));render();return;}
 if(action==='wizard-link'||action==='wizard-back'){const f=root.querySelector('[data-form="wizard"]');if(f)storeDraft(f);go(`add-property-${id}`,{id:query.get('id')||undefined});return;}
 if(action==='save-draft'){storeDraft(root.querySelector('[data-form="wizard"]'));toast('Draft saved locally.');return;}
 if(action==='clear-property-photos'){storeDraft(root.querySelector('[data-form="wizard"]'));attachments=[];store.transaction(()=>{store.state.draft.photos=[];store.state.draft.cover='';});render();return;}
 if(action==='delete-unit'){confirmAction('Delete this unit?','confirm-delete-unit',id);return;}
 if(action==='confirm-delete-unit'){store.deleteUnit(id);if(screen==='unit-details'){go('units');return;}closeAndRender('Unit deleted.');return;}
 if(action==='delete-property'){confirmAction('Delete this fictional property?','confirm-delete-property',id);return;}
 if(action==='confirm-delete-property'){store.deleteProperty(id);if(screen==='property-details'){go('properties');return;}closeAndRender('Sample property deleted.');return;}
 if(action==='new-booking'){show('Create booking',bookingForm());return;}
 if(action==='new-payment'){show('Record simulated payment',paymentForm());return;}
 if(action==='new-unit'||action==='edit-unit'){show(action==='new-unit'?'Add unit':'Edit unit',unitForm(id));return;}
 if(action==='new-contract'){show('Create sample contract',form('contract',info('SAMPLE DOCUMENT · Not a legally executed agreement')+select('Approved booking','bookingId',store.records('bookings').filter(b=>['approved','confirmed'].includes(b.status)).map(b=>[b.id,`${propName(b.propertyId)} · ${b.id}`]))+field('Contract title','title','Sample rental agreement'),'Create sample contract'));return;}
 if(action==='new-maintenance'){show('Submit maintenance request',maintenanceForm());return;}
 const detailTypes={'booking-details':'bookings','payment-details':'payments','contract-details':'contracts','maintenance-details':'maintenance'};
 if(detailTypes[action]){details(detailTypes[action],id);return;}
 if(['approve-booking','reject-booking','cancel-booking','verify-payment','approve-maintenance','reject-maintenance'].includes(action)){confirmAction('Update the selected sample record?',`confirm-${action}`,id);return;}
 if(action.startsWith('confirm-')){const target=action.slice(8);if(target==='approve-booking')store.updateBooking(id,'approved');else if(target==='reject-booking')store.updateBooking(id,'rejected');else if(target==='cancel-booking')store.updateBooking(id,'cancelled');else if(target==='verify-payment')store.verifyPayment(id);else if(target==='approve-maintenance')store.updateMaintenance(id,'approved');else if(target==='reject-maintenance')store.updateMaintenance(id,'rejected');else if(target==='reset'){store.reset();if(!store.user){go('login');return;}}closeAndRender('Sample records updated locally.');return;}
 if(action==='contract-status'||action==='maintenance-status'){const contract=action==='contract-status';show('Change demonstration status',form(action,`<input type="hidden" name="id" value="${h(id)}">`+select('Status','status',contract?['draft','active','expired','terminated']:['pending approval','approved','rejected','in progress','completed']),'Update demo status'));return;}
 if(action==='new-person'){show(id==='owners'?'Add owner':'Add tenant',form('person',`<input type="hidden" name="kind" value="${h(id)}">`+field('Name','name')+field('Demo email','email','','email'),'Add sample person'));return;}
 if(action==='person-details'){const [kind,key]=id.split(':');const person=store.state[kind].find(p=>p.id===key);show('Sample profile',pairs([['Name',person.name],['Email',person.email]])+actionBar(link(kind==='owners'?'Properties':'Contracts',kind==='owners'?'properties':'contracts')));return;}
 if(action==='new-document'){show('Add sample document',form('document',info('Only a sample reference is stored. No file is uploaded.')+field('Document title','title')+select('Property','propertyId',store.properties().map(p=>[p.id,name(p)])),'Add sample reference'));return;}
 if(action==='new-furniture'){show('Add inventory item',form('furniture',field('Item name','name')+field('Room','room')+field('Quantity','quantity','1','number',true,'min="1"')+select('Property','propertyId',store.properties().map(p=>[p.id,name(p)])),'Add sample item'));return;}
 if(action==='furniture-condition'){show('Update condition',form('furniture-condition',`<input type="hidden" name="id" value="${h(id)}">`+select('Condition','condition',['good','damaged','not assessed']),'Save sample condition'));return;}
 if(action==='furniture-details'){const item=store.records('furniture').find(f=>f.id===id);show('Furniture inventory',pairs(Object.entries(item).map(([k,v])=>[k,String(v)]))+btn('Close','close'));return;}
 if(action==='print'){window.print();return;}
 if(action==='download-contract'){const c=store.records('contracts').find(c=>c.id===id);download(`SAMPLE-CONTRACT-${id}.txt`,`SAMPLE DOCUMENT — NOT LEGALLY EXECUTED\n${c.title}\nProperty: ${propName(c.propertyId)}\nTenant: ${tenantName(c.tenantId)}\n${c.start} to ${c.end}\n${store.currency(c)} ${c.amount}\nStatus: ${c.status} (DEMO)\nNo signatures, payment or legal execution.`);return;}
 if(action==='download-document'){const d=store.records('documents').find(d=>d.id===id);download(`SAMPLE-${id}.txt`,`SAMPLE REFERENCE — NOT AN ORIGINAL DOCUMENT\n${d.title}\n${propName(d.propertyId)}\nFictional demo data only.`);return;}
 if(action==='export'){let rows=id==='properties'?store.properties({browse:store.user.role==='tenant'}):store.records(id);if(search)rows=rows.filter(r=>JSON.stringify(r).toLowerCase().includes(search.toLowerCase()));const keys=rows.length?Object.keys(rows[0]).filter(k=>!['photos','cover','comments','passwordHash'].includes(k)):['message'];const csv=[['DEMONSTRATION DATA — NOT REAL FINANCIAL RECORDS'],keys,...rows.map(r=>keys.map(k=>String(r[k]??'')))].map(row=>row.map(v=>`"${String(v).replace(/^[=+@-]/,"'").replaceAll('"','""')}"`).join(',')).join('\r\n');download(`Aqar-SAMPLE-${id}.csv`,'\uFEFF'+csv,'text/csv;charset=utf-8');return;}
 if(action==='reset'){confirmAction('Reset all fictional data on this device?','confirm-reset','');return;}
 if(action==='expire'){store.expire();go('session-expired');return;}
 if(action==='read-all'||action==='read-notification'){store.transaction(()=>store.records('notifications').filter(n=>action==='read-all'||n.id===id).forEach(n=>n.read=true));render();return;}
 notice();
 }catch(error){formError(error);}});
document.addEventListener('input',event=>{if(event.target.id==='demo-search'){search=event.target.value;page=1;const pos=event.target.selectionStart;render();const input=document.getElementById('demo-search');input.focus();input.setSelectionRange(pos,pos);}});
document.addEventListener('change',async event=>{try{if(['demo-filter','demo-city','demo-category','demo-country'].includes(event.target.id)){if(event.target.id==='demo-country'){country=event.target.value;city='all';}if(event.target.id==='demo-filter')filter=event.target.value;if(event.target.id==='demo-city')city=event.target.value;if(event.target.id==='demo-category')category=event.target.value;page=1;render();}
 if(event.target.name==='propertyId'&&event.target.closest('[data-form="booking"]')){const f=event.target.closest('form'),id=event.target.value;f.querySelector('[name="unitId"]').innerHTML=store.state.units.filter(u=>u.propertyId===id&&!['maintenance','unavailable'].includes(u.status)).map(u=>`<option value="${h(u.id)}">${h(u.name)} · ${h(money(u.price,u))}</option>`).join('');}
 if(event.target.matches('[data-photos]')){const files=[...event.target.files];if(files.length>4||files.some(f=>f.size>500000||!['image/png','image/jpeg','image/webp'].includes(f.type)))throw Error('Use up to four small PNG or JPEG photos.');attachments=await Promise.all(files.map(file=>new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);})));toast('Photos attached locally.');}
 }catch(error){event.target.value='';attachments=[];formError(error);}});
document.addEventListener('keydown',event=>{if(event.key==='Escape')document.body.classList.remove('sidebar-open');});
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)modal.close();}});
render();if(query.get('created'))toast('Sample records updated locally.');if(query.get('reset'))toast('Demo password changed.');
